import{_ as g,C as d,c as p,o as n,j as i,G as o,a8 as s,b as l,a,w as t,a9 as c}from"./chunks/framework.8HQ-OgOa.js";const b=JSON.parse('{"title":"Configuration Security and Permissions","description":"Configuration Security and Permissions","frontmatter":{"date":"2026-05-05T00:00:00.000Z","author":["Makitoid","Qoder"],"title":"Configuration Security and Permissions","description":"Configuration Security and Permissions"},"headers":[],"relativePath":"en/dev/system-architecture/config-management/config-security.md","filePath":"en/dev/system-architecture/config-management/config-security.md"}'),m={name:"en/dev/system-architecture/config-management/config-security.md"};function f(P,e,y,h,T,A){const u=d("ArticleMetadata"),r=d("Mermaid");return n(),p("div",null,[e[4]||(e[4]=i("h1",{id:"configuration-security-and-permissions",tabindex:"-1"},[a("Configuration Security and Permissions "),i("a",{class:"header-anchor",href:"#configuration-security-and-permissions","aria-label":'Permalink to "Configuration Security and Permissions"'},"​")],-1)),o(u),e[5]||(e[5]=s('<h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>This document focuses on the security and permission management of the InkCanvasForClass configuration system, structured around the following topics:</p><ul><li>Sensitive configuration entry protection mechanisms and access control</li><li>Configuration file permission management (file system permissions, user group access control, process isolation)</li><li>Configuration data encryption and key management (including decryption workflows)</li><li>Auditing and monitoring (access logs, anomaly detection, security event response)</li><li>Protection measures (anti-tamper detection, integrity validation, malicious configuration prevention)</li><li>Best practices (safe configuration suggestions, risk assessment methods, security hardening)</li></ul><h2 id="project-structure" tabindex="-1">Project Structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project Structure&quot;">​</a></h2><p>Key modules related to configuration security are distributed as follows:</p><ul><li>Security Manager: Responsible for password/TOTP verification, key derivation, constant-time comparison, and TOTP generation/validation.</li><li>Process Protection Manager: Implements file and directory locking and isolation between processes.</li><li>Profile Manager: Provides profile file saving, applying, deleting, and legitimacy validation.</li><li>Security Settings Page: Provides UI toggles and interactions, linking the Security Manager and Process Protection Manager.</li><li>Logging &amp; Telemetry: Unifies log writing and anonymizes sensitive information for auditing and monitoring.</li><li>Device Identifier &amp; Encryption: Handles device ID generation, usage statistics file encryption/decryption, and integrity checks.</li></ul>',6)),(n(),l(c,null,{default:t(()=>[o(r,{id:"mermaid-79",class:"mermaid",graph:"graph%20TB%0ASM%5B%22SecurityManager%3Cbr%2F%3EPassword%2FTOTP%2FKey%20Derivation%22%5D%20--%3E%20SP%5B%22SecurityPage%3Cbr%2F%3ESettings%20Page%20UI%22%5D%0ACPM%5B%22ConfigProfileManager%3Cbr%2F%3EProfile%20Save%2FApply%2FDelete%22%5D%20--%3E%20PP%5B%22ProcessProtectionManager%3Cbr%2F%3EProcess%20Protection%2FFile%20Lock%22%5D%0ASP%20--%3E%20PP%0ASP%20--%3E%20SM%0ALOG%5B%22LogHelper%3Cbr%2F%3ELog%20Writing%2FConcurrency%20Protection%22%5D%20--%3E%20PP%0ALOG%20--%3E%20SM%0ADI%5B%22DeviceIdentifier%3Cbr%2F%3EDevice%20ID%2FUsage%20Stats%20Encryption%22%5D%20--%3E%20LOG%0ATU%5B%22TelemetryUploader%3Cbr%2F%3ETelemetry%20Upload%2FSensitive%20Info%20Anonymization%22%5D%20--%3E%20LOG%0AAPP%5B%22App.xaml.cs%3Cbr%2F%3ETLS%20Config%2FPlatform%20Compatibility%22%5D%20--%3E%20TU%0A"})]),fallback:t(()=>e[0]||(e[0]=[a(" Loading... ",-1)])),_:1})),e[6]||(e[6]=s('<h2 id="core-components" tabindex="-1">Core Components <a class="header-anchor" href="#core-components" aria-label="Permalink to &quot;Core Components&quot;">​</a></h2><ul><li>Security Manager (SecurityManager) <ul><li>Evaluates if passwords are enabled, check for password configuration presence, configure TOTP, and check for TOTP-only mode.</li><li>Password validation (PBKDF2 derivation + constant-time comparison) and TOTP generation/validation (time-step based).</li><li>Sets/changes passwords, clears passwords, and generates TOTP secret keys.</li></ul></li><li>Process Protection Manager (ProcessProtectionManager) <ul><li>Enables/disables process protection, recursively locking key files and directories under the application root directory.</li><li>Write latch mechanism and degraded release strategy to prevent deadlocks and prolonged blocking.</li><li>White-listed directories excluded from locking (e.g., Logs, Configs, Saves, Backups, AutoUpdate).</li></ul></li><li>Profile Manager (ConfigProfileManager) <ul><li>Enforces directory existence, lists, saves, applies, and deletes configuration profiles.</li><li>Validates JSON legitimacy before applying a profile, combining with process protection for safe writing.</li></ul></li><li>Security Settings Page (SecurityPage) <ul><li>UI toggles and interactions: enable/disable password, enable/reset TOTP, and enforce verification prompts for various scenarios.</li><li>Invokes the Security Manager for verification and changes, interfacing with process protection controls.</li></ul></li><li>Logging &amp; Telemetry (LogHelper, TelemetryUploader) <ul><li>Unifies log writing with concurrent protection and date partitioning.</li><li>Regular-expression-based anonymization of sensitive information before telemetry upload.</li></ul></li><li>Device Identifier &amp; Encryption (DeviceIdentifier) <ul><li>Generates device IDs based on hardware fingerprints.</li><li>Encrypts usage statistics files using SHA256-derived keys and XOR operations, with integrity checksum validation.</li></ul></li></ul><h2 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h2><p>The overall architecture of configuration security and permissions is built around four dimensions: &quot;Authentication &amp; Authorization&quot;, &quot;Process Isolation &amp; File Protection&quot;, &quot;Data Encryption &amp; Integrity Validation&quot;, and &quot;Auditing &amp; Monitoring&quot;.</p>',4)),(n(),l(c,null,{default:t(()=>[o(r,{id:"mermaid-203",class:"mermaid",graph:"sequenceDiagram%0Aparticipant%20U%20as%20%22User%22%0Aparticipant%20SP%20as%20%22Security%20Settings%20Page%22%0Aparticipant%20SM%20as%20%22Security%20Manager%22%0Aparticipant%20CPM%20as%20%22Profile%20Manager%22%0Aparticipant%20PP%20as%20%22Process%20Protection%20Manager%22%0Aparticipant%20FS%20as%20%22File%20System%22%0AU-%3E%3ESP%20%3A%20Toggle%20%22Enable%20Password%2FEnable%20TOTP%22%0ASP-%3E%3ESM%20%3A%20PromptAndVerifyPasswordOrTotpAsync()%0ASM--%3E%3ESP%20%3A%20Verification%20Result%0Aalt%20Enable%20Password%0ASP-%3E%3ESM%20%3A%20SetPassword()%2FPromptSetNewPasswordAsync()%0ASM--%3E%3ESP%20%3A%20Success%2FFailure%0Aelse%20Enable%20TOTP%0ASP-%3E%3ESM%20%3A%20GenerateTotpSecret()%0ASM--%3E%3ESP%20%3A%20Return%20secret%20key%0Aend%0AU-%3E%3ECPM%20%3A%20Save%2FApply%2FDelete%20profile%20file%0ACPM-%3E%3EPP%20%3A%20WithWriteAccess(TargetPath)%0APP-%3E%3EFS%20%3A%20Write%20in%20protected%20mode%0AFS--%3E%3ECPM%20%3A%20Write%20Complete%0A"})]),fallback:t(()=>e[1]||(e[1]=[a(" Loading... ",-1)])),_:1})),e[7]||(e[7]=s('<h2 id="detailed-component-analysis" tabindex="-1">Detailed Component Analysis <a class="header-anchor" href="#detailed-component-analysis" aria-label="Permalink to &quot;Detailed Component Analysis&quot;">​</a></h2><h3 id="security-manager-password-totp" tabindex="-1">Security Manager (Password &amp; TOTP) <a class="header-anchor" href="#security-manager-password-totp" aria-label="Permalink to &quot;Security Manager (Password &amp; TOTP)&quot;">​</a></h3><ul><li>Password Protection <ul><li>PBKDF2-RFC2898 derived keys, configurable iterations, salt, and hash length.</li><li>Constant-time comparison to prevent timing side-channel attacks.</li><li>Set/change/clear password interfaces interacting with the UI.</li></ul></li><li>TOTP Protection <ul><li>6-digit dynamic codes based on time steps (30 seconds).</li><li>Base32 encoded secrets, supporting a step tolerance of ±1.</li><li>UI prompts and logical branching for TOTP-only and hybrid password/TOTP modes.</li></ul></li><li>Access Control <ul><li>Mandatory verification for multiple scenarios: application exit, entering settings, resetting configuration, and modifying or clearing name lists.</li><li>Interlocks with the settings page to dynamically enable/disable UI toggles based on feature statuses.</li></ul></li></ul>',3)),(n(),l(c,null,{default:t(()=>[o(r,{id:"mermaid-273",class:"mermaid",graph:"flowchart%20TD%0AStart(%5B%22Enter%20Security%20Verification%22%5D)%20--%3E%20CheckCfg%5B%22Check%20Password%2FTOTP%20Configuration%22%5D%0ACheckCfg%20--%3E%20Mode%7B%22TOTP%20Only%20Mode%3F%22%7D%0AMode%20--%3E%20%7CYes%7C%20AskTOTP%5B%22Prompt%20for%20TOTP%22%5D%0AMode%20--%3E%20%7CNo%7C%20AskPwdOrTotp%5B%22Prompt%20for%20Password%20or%20TOTP%22%5D%0AAskTOTP%20--%3E%20VerifyTOTP%5B%22VerifyTotp()%20Validation%22%5D%0AAskPwdOrTotp%20--%3E%20VerifyPwd%5B%22VerifyPassword()%20Validation%22%5D%0AVerifyTOTP%20--%3E%20Ok%7B%22Validation%20Passed%3F%22%7D%0AVerifyPwd%20--%3E%20Ok%0AOk%20--%3E%20%7CYes%7C%20Allow%5B%22Allow%20and%20return%20true%22%5D%0AOk%20--%3E%20%7CNo%7C%20Deny%5B%22Deny%20and%20return%20false%22%5D%0A"})]),fallback:t(()=>e[2]||(e[2]=[a(" Loading... ",-1)])),_:1})),e[8]||(e[8]=i("h2",{id:"dependency-analysis",tabindex:"-1"},[a("Dependency Analysis "),i("a",{class:"header-anchor",href:"#dependency-analysis","aria-label":'Permalink to "Dependency Analysis"'},"​")],-1)),e[9]||(e[9]=i("ul",null,[i("li",null,"The Security Settings Page depends on the Security Manager and the Process Protection Manager."),i("li",null,"The Profile Manager depends on the Process Protection Manager for safe writing."),i("li",null,"Logging and Telemetry depend on the Process Protection Manager and the Security Manager (for sensitive data processing)."),i("li",null,"The Device Identifier module is standalone but coordinates with logging/telemetry to form an auditing and monitoring loop.")],-1)),(n(),l(c,null,{default:t(()=>[o(r,{id:"mermaid-299",class:"mermaid",graph:"graph%20LR%0ASP%5B%22SecurityPage%22%5D%20--%3E%20SM%5B%22SecurityManager%22%5D%0ASP%20--%3E%20PP%5B%22ProcessProtectionManager%22%5D%0ACPM%5B%22ConfigProfileManager%22%5D%20--%3E%20PP%0ALOG%5B%22LogHelper%22%5D%20--%3E%20PP%0ALOG%20--%3E%20SM%0ADI%5B%22DeviceIdentifier%22%5D%20--%3E%20LOG%0ATU%5B%22TelemetryUploader%22%5D%20--%3E%20LOG%0AAPP%5B%22App.xaml.cs%22%5D%20--%3E%20TU%0A"})]),fallback:t(()=>e[3]||(e[3]=[a(" Loading... ",-1)])),_:1})),e[10]||(e[10]=s('<h2 id="performance-considerations" tabindex="-1">Performance Considerations <a class="header-anchor" href="#performance-considerations" aria-label="Permalink to &quot;Performance Considerations&quot;">​</a></h2><ul><li>PBKDF2 iteration count is high (approx. 120,000 iterations), causing CPU overhead during validation and derivation. It is recommended to execute these operations on background threads.</li><li>Write latches and degraded lock release strategies in process protection prevent long blocks, enhancing concurrent writing stability.</li><li>Log writing uses concurrent protection and date partitioning, reducing IO contention and preventing single files from becoming too large.</li><li>TOTP verification includes a ±1 step tolerance to balance user experience and security.</li></ul><p>[This section is general guidance and does not analyze specific files]</p><h2 id="troubleshooting-guide" tabindex="-1">Troubleshooting Guide <a class="header-anchor" href="#troubleshooting-guide" aria-label="Permalink to &quot;Troubleshooting Guide&quot;">​</a></h2><ul><li>Password/Verification Code Validation Fails <ul><li>Check whether the system is in TOTP-only or hybrid password/TOTP mode.</li><li>Verify input length and format (TOTP is a 6-digit number).</li></ul></li><li>Profile Saving/Applying Fails <ul><li>Check the log for records such as &quot;Failed to save profile&quot;, &quot;Failed to apply profile&quot;, or &quot;Invalid profile format&quot;.</li><li>Confirm if the target path exists and whether it is locked by process protection.</li></ul></li><li>Process Protection Triggers Write Timeout <ul><li>Check the log for warning messages: &quot;Write latch timeout. Degrading to release target path lock before writing.&quot;</li><li>Check if any processes are holding file handles for a prolonged duration.</li></ul></li><li>Telemetry Upload Anomaly <ul><li>Verify if anonymization rules cover the target sensitive fields.</li><li>Confirm network connectivity and Sentry service availability.</li></ul></li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>InkCanvasForClass&#39;s configuration security system forms a closed loop via &quot;Strong Authentication (Password/TOTP) + Process Isolation (File Locking) + Data Encryption (PBKDF2/SHA256/XOR) + Auditing &amp; Monitoring (Logs/Anonymization/Telemetry)&quot;. In combination with reasonable access controls and protection policies, it effectively minimizes the risks of configuration tampering, leaks, and abuse.</p><p>[This section is a summary and does not analyze specific files]</p><h2 id="appendix" tabindex="-1">Appendix <a class="header-anchor" href="#appendix" aria-label="Permalink to &quot;Appendix&quot;">​</a></h2><h3 id="configuration-security-best-practices" tabindex="-1">Configuration Security Best Practices <a class="header-anchor" href="#configuration-security-best-practices" aria-label="Permalink to &quot;Configuration Security Best Practices&quot;">​</a></h3><ul><li>Password &amp; TOTP <ul><li>Enable at least password or TOTP; enabling both and turning on &quot;TOTP Only Mode&quot; is recommended to simplify user input.</li><li>Enforce secondary verification for high-risk operations: exiting the app, entering settings, resetting configuration, and modifying or clearing name lists.</li></ul></li><li>File System &amp; Process Isolation <ul><li>Keep process protection enabled; regularly check logs for write latch timeout warnings.</li><li>Plan the directory structure logically, avoiding placing sensitive configurations in white-listed directories.</li></ul></li><li>Data Encryption &amp; Integrity <ul><li>Use SHA256-derived keys and checksum mechanisms for sensitive files like usage statistics.</li><li>Validate JSON legitimacy before applying configuration profiles.</li></ul></li><li>Auditing &amp; Monitoring <ul><li>Enable logging with date partitioning; configure alerts for anomalous writes and verification failures.</li><li>Anonymize telemetry data strictly before uploading to prevent sensitive information leaks.</li></ul></li><li>TLS &amp; Platform Compatibility <ul><li>Dynamically relax TLS protocols in older Windows environments to guarantee communication while monitoring security baselines.</li></ul></li></ul><p>[This section is general guidance and does not analyze specific files]</p>',12))])}const v=g(m,[["render",f]]);export{b as __pageData,v as default};
